'use strict';
const $ = (selector, root=document) => root.querySelector(selector);
const $$ = (selector, root=document) => [...root.querySelectorAll(selector)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const COLORS=['#337566','#c7a76d','#648daa','#cf9074','#8f9d76'];
const ROLE={unassigned:'未划分',seed:'种子集',pool:'训练池',val:'验证集',test:'测试集',gap:'隔离带'};
const STATES={recovering:'核验进程中',queued:'等待启动',running:'执行中',cancelling:'正在停止',completed:'已完成',failed:'失败',cancelled:'已停止',interrupted:'中断',planned:'训练计划',predicted:'待审核',reviewed:'已审核'};
const PAGES={overview:'实验概览',data:'视频与数据',label:'人工标注',train:'模型训练',auto:'自动标注与审核',results:'结果对比'};
const ACTIONS={'import-yolo':'导入已有图片',extract:'视频抽帧',split:'固定数据划分','import-labels':'导入人工标注',train:'模型训练',autolabel:'自动标注',evaluate:'测试集评价',time:'保存标注工时',report:'生成实验报告'};
const S={token:'',overview:null,details:null,id:localStorage.getItem('alab-project')||'',page:'overview',role:'all',galleryPage:0,round:'',trainingModel:'',busy:false,video:null,preview:null};
const timeDrafts=new Map();
let timerState=null, pollBusy=false, toastTimeout, dialogGeneration=0, refreshGeneration=0;

async function api(path, payload){
  const options=payload === undefined ? {} : {method:'POST',headers:{'Content-Type':'application/json','X-Lab-Token':S.token},body:JSON.stringify(payload)};
  const response=await fetch(path,options), data=await response.json();
  if(!response.ok) throw new Error(data.error||'操作失败');
  return data;
}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.hidden=true,error?9000:4500)}
function selected(){return S.overview?.projects.find(p=>p.id===S.id)}
function activeJobs(){return (S.overview?.jobs||[]).filter(j=>['queued','running','cancelling','recovering'].includes(j.status))}
function completedModels(){return (S.details?.models||[]).filter(m=>m.status==='completed')}
function reviewedRounds(){return (S.details?.rounds||[]).filter(r=>r.status==='reviewed')}
function pct(n){return n==null?'—':(n*100).toFixed(1)+'%'}
function minutes(n){return n==null?'—':(n/60).toFixed(1)}
function badge(state){return `<span class="badge ${['failed','cancelled','interrupted'].includes(state)?'danger':['running','queued','predicted','cancelling','recovering'].includes(state)?'warn':''}">${esc(STATES[state]||state)}</span>`}
function fileUrl(path){return `/api/file?id=${encodeURIComponent(S.id)}&path=${encodeURIComponent(path)}`}
function btn(label, attrs='',primary=false){return `<button class="btn ${primary?'primary':''}" ${attrs}>${label}</button>`}
function empty(title,description='',action=''){return `<div class="empty"><span class="empty-symbol">⌗</span><h3>${title}</h3><p>${description}</p>${action}</div>`}
function panel(title,body,subtitle='',right=''){return `<section class="panel"><div class="panel-top"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${right}</div>${body}</section>`}
function heading(title,subtitle,eyebrow,buttons=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="heading-buttons">${buttons}</div></div>`}
function field(name,label,value='',type='text',options=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${options}></div>`}
function select(name,label,choices,value='',required=true){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}" ${required?'required':''}>${choices.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></div>`}
function frameCaption(frame){return frame.source_kind==='image'?'图片 '+(frame.frame_index+1):(Number(frame.timestamp)||0).toFixed(1)+' 秒'}
function formsPayload(form){const result={};new FormData(form).forEach((v,k)=>result[k]=String(v).trim());return result}
function requireProject(){if(!S.details) throw new Error('请先新建或选择实验。')}

async function refresh(render=true){
  const generation=++refreshGeneration,requestedId=S.id,overview=await api('/api/overview');
  if(generation!==refreshGeneration||S.id!==requestedId)return false;
  const id=overview.projects.some(p=>p.id===requestedId)?requestedId:overview.projects.find(p=>!p.error)?.id||'';
  const details=id?await api('/api/project?id='+id):null;
  if(generation!==refreshGeneration||S.id!==requestedId)return false;
  S.overview=overview;S.id=id;S.details=details;reconcileTimeSaves();
  updateSidebar();
  updateDock();
  if(render) renderPage();
  return true;
}
function updateSidebar(){
  const selector=$('#project-select');selector.innerHTML=S.overview.projects.length?S.overview.projects.map(p=>`<option value="${p.id}" ${p.id===S.id?'selected':''}>${esc(p.title)}${p.config?.synthetic_smoke_test?' · 示例':''}</option>`).join(''):'<option value="">尚未创建实验</option>';
  $('#runtime-label').textContent=`${S.overview.default_model.replace('.yaml','')} · ${S.overview.runtime.ultralytics?`Ultralytics ${S.overview.runtime.ultralytics}`:'训练依赖未安装'}`;
  localStorage.setItem('alab-project',S.id);
}
function navigate(page){S.page=page;S.galleryPage=0;renderPage();window.scrollTo({top:0,behavior:'smooth'})}
function renderPage(preserve=false){
  const drafts=preserve?$$('#content form[data-dirty]').map(form=>({id:form.id,values:[...form.elements].filter(e=>e.name).map(e=>({name:e.name,value:e.value,checked:e.checked,type:e.type})),focus:form.contains(document.activeElement)?{name:document.activeElement.name,start:document.activeElement.selectionStart,end:document.activeElement.selectionEnd}:null})):[];
  $$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===S.page));$('#breadcrumb').textContent=PAGES[S.page];
  let content;
  if(!S.details) content=welcome();
  else content=({overview:overviewPage,data:dataPage,label:labelPage,train:trainPage,auto:autoPage,results:resultsPage}[S.page])();
  if(S.details){const job=(S.overview.jobs||[]).filter(j=>j.project_id===S.id).sort((a,b)=>b.created_at.localeCompare(a.created_at))[0];if(job)content+=panel('最近任务',`<div class="job-row"><div>${ACTIONS[job.action]} · ${esc(job.payload.name||job.payload.round||job.payload.subset||'')}<small>${new Date(job.created_at).toLocaleString('zh-CN')}</small></div><div class="buttons">${badge(job.status)}${btn('查看日志',`data-log="${job.id}"`)}</div></div>${job.error?`<div class="error-box">${esc(job.error.trim().split(/\r?\n/).filter(Boolean).at(-1))}</div>`:''}`,'完成、失败和停止的任务都可以查看详细日志。')}
  $('#content').innerHTML=content;
  if(S.details?.config.synthetic_smoke_test) $('#content').insertAdjacentHTML('afterbegin','<div class="warning-note">模拟示例实验 · 仅用于熟悉操作和验证工具，指标不代表真实标注效果。</div>');
  bindPage();
  for(const draft of drafts){const form=document.getElementById(draft.id);if(!form)continue;form.dataset.dirty='true';for(const saved of draft.values){const element=[...form.elements].find(e=>e.name===saved.name&&(!['checkbox','radio'].includes(saved.type)||e.value===saved.value));if(!element)continue;if(['checkbox','radio'].includes(saved.type))element.checked=saved.checked;else element.value=saved.value}if(form.id==='train-form')$('#f-init',form).onchange();if(draft.focus){const input=[...form.elements].find(e=>e.name===draft.focus.name);input?.focus({preventScroll:true});if(draft.focus.start!=null)input?.setSelectionRange(draft.focus.start,draft.focus.end)}}
  if(S.preview&&S.page==='data') showPreview(S.preview);
  restoreTimeDraft();if(timerState) updateTimer();
}

function welcome(){return `${heading('开始你的第一轮实验','从一段视频、十几张人工标注，走到可比较的实验结果。','WELCOME TO YOUR LAB',btn('导入已有实验','data-import')+btn('导入 YOLO 图片','data-yolo'))}<div class="welcome"><div class="eyebrow">LESS LABELING, MORE LEARNING</div><h1>让每一轮标注，<br>都有看得见的进步。</h1><p>记录模型从零起步的表现，查看自动标注需要多少修正，再用固定测试集评价新增数据的帮助。</p>${btn('＋ 创建第一个实验','data-new',true)}<div class="welcome-grid" aria-hidden="true">${['▧','⌑','↗','◇','✧','▥','⌗','⤴','◎'].map(x=>`<span>${x}</span>`).join('')}</div></div><div class="three-col"><div class="intro-card"><div class="intro-num">01 / PREPARE</div><h3>准备视频和种子数据</h3><p>按需抽帧，固定训练、验证和测试段。在 X-AnyLabeling 中完成起步标注。</p></div><div class="intro-card"><div class="intro-num">02 / ITERATE</div><h3>训练、预标注与审核</h3><p>使用与原项目一致的 YOLO26s-OBB。从随机权重训练，逐轮添加合格标注。</p></div><div class="intro-card"><div class="intro-num">03 / COMPARE</div><h3>看质量，也看时间</h3><p>对照原始预测与审核结果，比较固定测试集指标，记录获得合格标注的工时。</p></div></div>`}
function stepData(){const d=S.details;return [{title:d.config.input_kind==='yolo_images'?'导入图片':'视频抽帧',hint:'准备实验图片',page:'data',done:d.manifest.frames.length>0},{title:'人工标注',hint:'种子 / 验证 / 测试',page:'label',done:['seed','val','test'].every(k=>d.annotations[k])},{title:'种子训练',hint:'从零训练 M0',page:'train',done:completedModels().length>0},{title:'预标注与审核',hint:'查看本轮质量',page:'auto',done:reviewedRounds().length>0},{title:'测试与对比',hint:'指标和人工作时',page:'results',done:d.models.some(m=>m.evaluation)}]}
function overviewPage(){
 const d=S.details, entry=selected(), steps=stepData(), next=steps.find(s=>!s.done)||steps[4], total=d.manifest.frames.length, models=completedModels(), rounds=reviewedRounds(), evaluated=models.filter(m=>m.evaluation), latest=evaluated.at(-1);
 const metrics=[[d.config.input_kind==='yolo_images'?'已导入图片':'已抽取图片',total,'张',`种子 ${d.summary.frames.seed} / 训练池 ${d.summary.frames.pool}`,'▧'],['训练模型',models.length,'个',`${d.models.filter(m=>m.status==='running').length} 个正在训练`,'↗'],['已审核轮次',rounds.length,'轮',`${rounds.reduce((s,r)=>s+r.frame_ids.length,0)} 张新增合格标注`,'✧'],['最新测试 mAP50–95',latest?pct(latest.evaluation.metrics.mAP50_95):'—','',latest?latest.name+' · 固定测试集':'完成模型评价后显示','▥']];
 const workflow=`<div class="steps">${steps.map((s,i)=>`<button class="step ${s.done?'done':s===next?'current':''}" data-go="${s.page}"><span class="step-number">${s.done?'✓':i+1}</span><span><strong>${s.title}</strong><small>${s.hint}</small></span></button>`).join('')}</div>`;
 const curveModel=d.models.filter(m=>['running','completed'].includes(m.status)).at(-1), training=curveModel?lineChart(curveModel.curve,[['train/box_loss','训练框损失',COLORS[0]],['val/box_loss','验证框损失',COLORS[1]]]):empty('曲线会在训练后出现','每个 epoch 的训练与验证损失会自动显示。',btn('开始训练','data-go="train"'));
 const recent=(S.overview.jobs||[]).filter(j=>j.project_id===S.id).sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,4);
 return `${heading(esc(entry.title),'把模型质量和标注成本放在同一轮实验中观察。','EXPERIMENT / OVERVIEW',`<span class="badge">${esc(d.config.model_yaml.replace('.yaml',''))}</span>${btn('打开实验目录','data-folder="root"')}`)}${workflow}<div class="metric-grid">${metrics.map(([l,v,u,n,icon])=>`<div class="metric"><span class="metric-icon">${icon}</span><div class="metric-label">${l}</div><div class="metric-value">${v}<small>${u}</small></div><div class="metric-note">${n}</div></div>`).join('')}</div><div class="callout"><div><h3>下一步 · ${next.title}</h3><p>${next.page==='label'?'完成三个子集的人工标注后导入。测试集会一直保留，不加入训练。':next.page==='data'?'选择视频，设置抽帧时间和间隔，再固定数据划分。':next.page==='train'?'检查种子标注和训练配置，训练第一轮模型。':next.page==='auto'?'使用已训练模型预标注新的图片，逐张审核并记录工时。':'在相同测试集评价模型，再生成结果报告。'}</p></div>${btn('进入'+next.title,`data-go="${next.page}"`,true)}</div><div class="two-col">${panel('训练过程',training,'记录模型学习过程',curveModel?`<span class="badge">${esc(curveModel.name)}</span>`:'')}${panel('数据组成',splitOverview(),d.summary.split_locked?'固定划分已锁定':'完成抽帧后固定划分')}</div><div class="half-col">${panel('模型记录',models.length?modelTable(models.slice(-3)):empty('尚无训练模型','从种子标注开始训练 M0。'))}${panel('最近操作',recent.length?recent.map(j=>`<div class="job-row"><div>${ACTIONS[j.action]}<small>${esc(j.payload.name||j.payload.round||new Date(j.created_at).toLocaleString('zh-CN'))}</small></div><div class="buttons">${badge(j.status)}${btn('日志',`data-log="${j.id}"`,false)}</div></div>`).join(''):empty('准备开始','每次操作的状态和日志会保存在这里。'))}</div>`;
}
function splitOverview(){const counts=S.details.summary.frames,total=Object.values(counts).reduce((a,b)=>a+b,0);if(!total)return empty('暂无图片','先从视频中抽帧。');const roles=['seed','pool','val','test','gap','unassigned'];return `<div class="split-bar">${roles.filter(r=>counts[r]).map((r,i)=>`<span style="--portion:${counts[r]};--bar-color:${COLORS[i%5]}" title="${ROLE[r]} ${counts[r]}"></span>`).join('')}</div><div class="help-lines">${roles.filter(r=>counts[r]).map((r,i)=>`<div class="report-stat"><span><i style="color:${COLORS[i%5]}">●</i> ${ROLE[r]}</span><div class="bar-track"><div class="bar-fill" style="--portion:${counts[r]/total*100}%;--bar-color:${COLORS[i%5]}"></div></div><strong>${counts[r]} 张</strong></div>`).join('')}</div><p>验证和测试图片始终不进入自动标注池。</p>`}
function dataPage(){if(S.details.config.input_kind==='yolo_images')return imageDataPage();const locked=S.details.summary.split_locked;return `${heading('从视频准备实验图片','按时间抽帧、检查画面，再固定数据划分。','01 / DATA PREPARATION')}<div class="two-col">${panel('视频抽帧',`<form id="extract-form"><div class="field"><label for="video-path">视频文件</label><div class="input-action"><input id="video-path" name="video" placeholder="选择文件或粘贴完整视频路径" value="${esc(S.video?.path||'')}" required ${locked?'disabled':''}>${btn('选择文件','type="button" id="pick-video" '+(locked?'disabled':''))}</div></div><div class="field-row">${field('start','开始时间（秒）',0,'number','min="0" step="0.1"')}${field('end','结束时间（秒，可留空）','','number','min="0" step="0.1"')}</div><div class="field-row">${field('every','每隔多少秒抽一帧',1,'number','min="0.1" step="0.1" required')}${field('max_frames','本次最多抽取',150,'number','min="1" required')}</div><div class="field"><label for="timestamps">指定时间点（可选）</label><input id="timestamps" name="timestamps" placeholder="例如 0,2.5,10,18；填写后使用指定时间点"><p class="form-help">指定时间点适合按动作阶段选帧。所有抽帧应在固定划分前完成。</p></div><div class="buttons">${btn('查看视频画面','type="button" id="preview-video"')}${btn('开始抽帧','type="submit" '+(locked||activeJobs().length?'disabled':''),true)}</div>${locked?'<p class="form-help">数据划分已固定。新增视频请建立新实验。</p>':''}</form>`)}${panel('视频预览',`<div id="video-preview" class="video-preview">${empty('检查你要抽取的画面','选择视频后点击“查看视频画面”。')}</div><div class="field-row" style="margin-top:16px">${field('preview-second','预览时间（秒）',0,'number','min="0" step="0.1"')}<div class="field"><label>&nbsp;</label>${btn('跳到此帧','id="seek-preview"')}</div></div><div id="preview-caption" class="preview-caption"></div>`,'先确认视频、视角和动作范围')}</div><div class="two-col">${panel('固定数据划分',locked?`${splitOverview()}<div class="badge">✓ 数据划分已锁定</div><p>种子集从训练时间段均匀选出；边界附近留出隔离带。</p>`:`<form id="split-form"><div class="field-row">${field('seed_count','种子图片数',15,'number','min="1" required')}${field('gap_seconds','边界隔离间隔（秒）',2,'number','min="0" step="0.1" required')}</div><div class="field-row">${field('val_percent','验证集比例（%）',15,'number','min="1" max="98" required')}${field('test_percent','测试集比例（%）',20,'number','min="1" max="98" required')}</div><p class="form-help">按视频时间段隔离；固定后不能重新划分。剩余图片进入训练池。</p>${btn('固定划分并生成标注目录','type="submit" '+(!S.details.manifest.frames.length||activeJobs().length?'disabled':''),true)}</form>`)}${panel('怎样选帧更有价值',`<div class="help-lines"><div class="help-line"><span class="help-icon">1</span><div><strong>覆盖不同动作与视角</strong><p>先预览视频，选动作变化、遮挡与目标角度不同的时间点。</p></div></div><div class="help-line"><span class="help-icon">2</span><div><strong>种子集覆盖全部类别</strong><p>第一轮样本少，遗漏的类别无法有效学习。导入前检查类别覆盖。</p></div></div><div class="help-line"><span class="help-icon">3</span><div><strong>先固定评价基准</strong><p>验证段选模型，测试段比较结果。它们不会进入训练池。</p></div></div></div>`)}</div>${panel('抽帧图片',galleryHtml(),`${S.details.manifest.frames.length} 张图片 · 点击查看大图`)}`}
function imageDataPage(){const d=S.details;return `${heading('已有图片与固定分组','从 YOLO OBB 数据集导入，保留图片、已有标签和抽样清单。','01 / IMAGE DATA')}${panel('本轮数据组成',splitOverview(),'固定随机种子 '+d.config.seed)}${panel('数据使用方式',`<p>种子集用于 M0 初始训练，验证集选择模型，固定测试集用于 M0/M1 对比。训练池图片用于本轮自动标注与人工审核；已有参考标签单独保存，不进入 M0 训练或预测审核目录。</p><div class="buttons"><a class="btn" href="${fileUrl('reports/selection.csv')}" download>下载抽样清单</a>${btn('进入模型训练','data-go="train"',true)}</div>`)}${panel('抽样与标注说明',(d.config.import_warnings||[]).map(w=>`<p>${esc(w)}</p>`).join(''))}${panel('已导入图片',galleryHtml(),'点击图片查看大图及已有标注')}`}
function yoloDialog(){openDialog(`<div class="eyebrow">IMPORT YOLO OBB</div><h2>导入已有图片和标注</h2><p>选择包含 data.yaml、images/train、images/val 和对应 labels 的目录。自动读取类别，建立独立实验。</p><form id="yolo-form">${field('title','实验名称','','text','required')}${field('name','目录标识','','text','pattern="[A-Za-z0-9][A-Za-z0-9_-]{0,63}" required')}<div class="field"><label for="yolo-source">YOLO 数据集目录</label><div class="input-action"><input id="yolo-source" name="source" required placeholder="选择目录或粘贴完整路径">${btn('选择目录','type="button" id="pick-yolo-source"')}</div></div><div class="field-row">${field('train_count','初始训练图片',200,'number','min="1" required')}${field('val_count','本轮验证图片',50,'number','min="1" required')}</div><div class="field-row">${field('pool_count','自动标注与审核图片',200,'number','min="1" required')}${field('test_count','固定测试图片',50,'number','min="1" required')}</div>${field('seed','随机种子',42,'number','min="0" max="4294967295" required')}<p>验证图片从原 val 选择，其他三组从原 train 无交集抽样。已有审核池标签独立保存为参考。数据已打乱，同场景相关画面可能跨子集。</p>${btn('创建实验并导入','type="submit"',true)}</form>`);$('#pick-yolo-source').onclick=()=>safeAsync(async()=>{const r=await api('/api/pick',{kind:'directory'});if(r.path)$('#yolo-source').value=r.path});$('#yolo-form').onsubmit=e=>{e.preventDefault();const form=e.target;safeAsync(async()=>{const button=$('button[type="submit"]',form);button.disabled=true;try{const r=await api('/api/create-yolo',formsPayload(form));S.id=r.id;S.role='all';$('#dialog').close();await refresh();navigate('overview');toast('正在检查并导入图片，请查看任务进度')}finally{button.disabled=false}})}}
function labelPage(){const d=S.details;return `${heading('完成第一轮人工标注','用旋转框标注起步图片，同时准备固定的验证和测试答案。','02 / HUMAN ANNOTATION',btn('启动 X-AnyLabeling','data-folder="seed" data-launch'))}<div class="callout"><div><h3>标注在 X-AnyLabeling 中完成</h3><p>打开对应图片目录，JSON 保存到图片旁边。每张图片都需要保存，无目标图片保存空标注。</p></div><span class="badge">类别：${d.config.classes.map(esc).join(' / ')}</span></div><div class="three-col">${['seed','val','test'].map(role=>{const c=d.coverage[role];return `<section class="panel"><div class="eyebrow">${role.toUpperCase()}</div><h2>${ROLE[role]}</h2><p>${role==='seed'?'用于第一轮从零训练':role==='val'?'训练过程中选择最佳模型':'所有模型共用的最终评价集'}</p><div class="metric-value" data-coverage-count="${role}" style="margin:19px 0">${c.saved}<small>/ ${c.total} 张已保存</small></div><div class="split-bar" data-coverage-bar="${role}"><span style="--portion:${c.total?c.saved/c.total:0};--bar-color:${COLORS[0]}"></span><span style="--portion:${c.total?1-c.saved/c.total:1};--bar-color:#eef1e9"></span></div><div class="buttons">${btn('打开标注目录',`data-folder="${role}" ${!c.total?'disabled':''}`)}${btn(c.archived?'✓ 已归档':'导入标注',`data-import-label="${role}" ${c.archived||!c.total||activeJobs().length?'disabled':''}`,!c.archived)}</div><p class="form-help">${c.archived?'归档已固定，避免改变训练与评价基准。':'保存后点击导入，工具会校验整批图片的标注。'}</p></section>`}).join('')}</div><div class="half-col">${panel('标注前检查',`<ul class="note-list"><li>使用旋转框，类别名称与实验清单完全一致。</li><li>图片的每个目标都要标，框不要超过图片边界。</li><li>无目标图也应保存空 JSON，未保存不代表负样本。</li><li>种子集只需十几张；验证和测试图片也需完成人工标注。</li></ul>`)}${panel('记录种子标注工时',timeForm('seed'),'机器训练时间会另行记录，这里只填人工用时。')}</div>${panel('查看标注图片',galleryHtml(['seed','val','test']),'点击图片查看已保存的旋转框')}`}
function trainPage(){const d=S.details,ready=['seed','val','test'].every(k=>d.annotations[k]),models=completedModels();if(!d.models.some(m=>m.name===S.trainingModel))S.trainingModel=d.models.filter(m=>['running','completed'].includes(m.status)).at(-1)?.name||d.models.at(-1)?.name||'';const current=d.models.find(m=>m.name===S.trainingModel)||d.models.at(-1);return `${heading('训练你的实验模型','从随机权重起步，再加入审核后的新数据。','03 / MODEL TRAINING',`<span class="badge">${esc(d.config.model_yaml.replace('.yaml',''))}</span>`)}${!ready?'<div class="warning-note">开始训练前，请先导入种子、验证和测试集的人工标注。</div>':''}<div class="two-col">${panel('创建训练任务',`<form id="train-form"><div class="field-row">${field('name','模型名称',nextModelName(),'text','pattern="[A-Za-z0-9][A-Za-z0-9_-]{0,63}" required')}${select('init','初始化方式',[['scratch','从随机权重训练（默认）'],['continue','从父模型权重继续训练']])}</div><div id="parent-field" hidden>${select('from_model','父模型',[['','选择已训练模型'],...models.map(m=>[m.name,m.name])],'',false)}</div><div class="field-row triple">${field('epochs','训练轮数',100,'number','min="1" required')}${field('imgsz','输入尺寸',640,'number','min="32" step="32" required')}${field('batch','每批图片数',4,'number','min="1" required')}</div>${select('device','运行设备',S.overview.runtime.torch?[['0','GPU 0'],['cpu','CPU']]:[['cpu','CPU']],S.overview.runtime.torch?'0':'cpu')}<div class="field"><label>纳入训练的审核轮次</label>${reviewedRounds().length?reviewedRounds().map(r=>`<div class="check-row"><input type="checkbox" name="rounds" value="${esc(r.name)}" id="round-check-${esc(r.name)}"><label for="round-check-${esc(r.name)}">${esc(r.name)} · ${r.frame_ids.length} 张 · 来源模型 ${esc(r.model)}</label></div>`).join(''):'<p class="form-help">第一轮只使用种子图片。完成审核后，可在此选择新增轮次。</p>'}</div><div id="init-hint" class="form-help">使用实验中的结构 YAML 从零训练；不加载已有模型权重。</div><div class="buttons" style="margin-top:18px">${btn('检查训练数据','type="button" id="check-train" '+(!ready||activeJobs().length?'disabled':''))}${btn('开始训练','type="submit" '+(!ready||activeJobs().length||!S.overview.runtime.ultralytics?'disabled':''),true)}</div></form>`,'每个模型保留自己的数据快照与参数')}${panel('训练曲线',current?`${select('curve-model','查看模型',d.models.map(m=>[m.name,m.name]),current.name)}${lineChart(current.curve,[['train/box_loss','训练框损失',COLORS[0]],['val/box_loss','验证框损失',COLORS[1]]])}<p>已记录 ${current.curve.length} 个 epoch · ${badge(current.status)} ${esc(current.model_yaml.replace('.yaml',''))}</p>`:empty('尚未开始训练','启动后，曲线和日志会自动刷新。'),'训练与验证损失，随 epoch 自动更新')}</div>${panel('模型列表',d.models.length?modelTable(d.models):empty('准备训练 M0','上方检查数据后点击“开始训练”。'),'失败任务保留日志；重试请使用新名称')}`}
function nextModelName(){const names=new Set(S.details.models.map(m=>m.name));let i=0;while(names.has('M'+i))i++;return 'M'+i}
function nextRoundName(){const names=new Set(S.details.rounds.map(r=>r.name));let i=1;while(names.has('r'+i))i++;return 'r'+i}
function modelTable(models){return `<div class="table-wrap"><table><thead><tr><th>模型</th><th>初始化 / 结构</th><th>训练图片</th><th>状态</th><th>训练用时</th><th>测试 mAP50–95</th></tr></thead><tbody>${models.map(m=>`<tr><td class="model-name">${esc(m.name)}</td><td>${m.init==='scratch'?'从零训练':'继续训练'}<small>${esc(m.model_yaml||'')}</small></td><td>${m.counts?.train??'—'}</td><td>${badge(m.status)}</td><td>${minutes(m.machine_seconds)} 分钟</td><td>${m.evaluation?pct(m.evaluation.metrics.mAP50_95):'待评价'}</td></tr>`).join('')}</tbody></table></div>`}
function autoPage(){const d=S.details,models=completedModels(),rounds=d.rounds,used=new Set(rounds.filter(r=>['predicted','reviewed','running'].includes(r.status)).flatMap(r=>r.frame_ids)),available=d.manifest.frames.filter(f=>f.role==='pool'&&!used.has(f.id)).length;if(!rounds.some(r=>r.name===S.round))S.round=rounds.at(-1)?.name||'';const current=rounds.find(r=>r.name===S.round), archived=current?.status==='reviewed';return `${heading('查看预标注，完成这一轮审核','先保留原始预测，再删除误检、补漏和调整旋转框。','04 / AUTO LABELING')}<div class="two-col">${panel('生成新一轮预标注',`<form id="auto-form"><div class="field-row">${field('round','轮次名称',nextRoundName(),'text','required')}${select('model','来源模型',models.map(m=>[m.name,m.name]),models.at(-1)?.name)}</div><div class="field-row">${field('count','这一轮图片数',Math.min(S.details.config.input_kind==='yolo_images'?200:25,available)||25,'number',`min="1" max="${available||1}" required`)}${field('conf','置信度阈值',0.25,'number','min="0.01" max="1" step="0.01" required')}</div>${select('device','运行设备',[['0','GPU 0'],['cpu','CPU']],S.overview.runtime.torch?'0':'cpu')}<p class="form-help">当前还有 ${available} 张未使用的训练池图片。验证和测试图不参与预标注。</p>${btn('开始自动标注','type="submit" '+(!models.length||!available||activeJobs().length?'disabled':''),true)}</form>`)}${panel('审核流程',current?`${select('review-round','当前轮次',rounds.map(r=>[r.name,`${r.name} · ${STATES[r.status]||r.status}`]),current.name)}<div class="pill-row"><span class="badge">${current.frame_ids.length} 张图片</span><span class="badge">模型 ${esc(current.model)}</span>${badge(current.status)}</div><p>在 X-AnyLabeling 中打开编辑目录，逐张修正。原始预测目录不会被覆盖。</p><div class="buttons">${btn('打开审核目录',`data-folder="round" data-round="${esc(current.name)}" ${!['predicted','reviewed'].includes(current.status)?'disabled':''}`)}${btn('启动标注工具',`data-folder="round" data-round="${esc(current.name)}" data-launch ${!['predicted','reviewed'].includes(current.status)?'disabled':''}`)}</div><form id="review-import-form" style="margin-top:18px"><div class="check-row"><input id="review-confirm" name="reviewed" type="checkbox" required ${archived?'checked disabled':''}><label for="review-confirm">我已逐张审核，包括没有预测框的图片，并补齐了漏检目标。</label></div>${btn(archived?'✓ 已归档':'导入审核结果','type="submit" '+(archived||current.status!=='predicted'||activeJobs().length?'disabled':''),!archived)}</form>`:empty('等待第一轮预标注','生成后，在这里打开标注目录并导入修正结果。'))}</div>${current&&['predicted','reviewed'].includes(current.status)?`${panel('原始预测与审核结果',galleryHtml(null,current),`${esc(current.name)} · 点击图片并排查看两份旋转框`)}<div class="half-col">${panel('记录本轮人工作时',timeForm('review',current.name),'支持审核修正计时和纯人工基线记录')}${panel('审核时关注这些变化',`<div class="help-lines"><div class="help-line"><span class="help-icon">⌑</span><div><strong>删除误检，补齐漏检</strong><p>没有预测框的图片也必须检查。否则会低估漏检数量。</p></div></div><div class="help-line"><span class="help-icon">↻</span><div><strong>修正类别与旋转框</strong><p>达到与纯人工标注相同的质量标准后再导入。</p></div></div><div class="help-line"><span class="help-icon">◷</span><div><strong>工时是实测值</strong><p>审核修正与纯人工基线分开记录，不填基线就不会计算节省比例。</p></div></div></div>`)}</div>`:''}${panel('轮次记录',rounds.length?`<div class="table-wrap"><table><thead><tr><th>轮次</th><th>来源模型</th><th>图片</th><th>阈值</th><th>状态</th></tr></thead><tbody>${rounds.map(r=>`<tr><td class="model-name">${esc(r.name)}</td><td>${esc(r.model)}</td><td>${r.frame_ids.length}</td><td>${r.params.conf}</td><td>${badge(r.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('从 M0 开始第一轮','使用模型预测新的训练池图片。'))}`}
function resultsPage(){const d=S.details,models=completedModels(),report=d.report,evaluated=models.filter(m=>m.evaluation);return `${heading('比较质量与标注成本','模型提升和标注省时分别记录，才能判断自动标注的价值。','05 / RESULTS & EVIDENCE',btn('更新实验报告','id="generate-report" '+(!d.summary.split_locked||activeJobs().length?'disabled':''),true))}<div class="two-col">${panel('固定测试集评价',`<form id="evaluate-form">${models.length?models.map(m=>`<div class="model-select"><input id="eval-${esc(m.name)}" type="checkbox" name="models" value="${esc(m.name)}" ${m.evaluation?'disabled':'checked'}><label for="eval-${esc(m.name)}">${esc(m.name)}<small> · ${m.counts.train} 张训练图</small></label>${m.evaluation?'<span class="badge">已评价</span>':''}</div>`).join(''):empty('暂无可评价模型','完成训练后，在这里选择模型。')}<div style="margin-top:15px">${select('device','运行设备',[['0','GPU 0'],['cpu','CPU']],S.overview.runtime.torch?'0':'cpu')}</div>${btn('评价选中的模型','type="submit" '+(!models.some(m=>!m.evaluation)||activeJobs().length?'disabled':''),true)}</form><p class="form-help">使用同一份人工测试集。已保存的评价结果不会覆盖。</p>`)}${panel('模型指标对比',evaluated.length?barChart(evaluated.map(m=>m.name),[{label:'mAP50',color:COLORS[1],values:evaluated.map(m=>m.evaluation.metrics.mAP50)},{label:'mAP50–95',color:COLORS[0],values:evaluated.map(m=>m.evaluation.metrics.mAP50_95)}]):empty('评价后显示图表','精确率、召回率和 mAP 会保存在模型记录中。'))}</div>${panel('测试指标明细',evaluated.length?`<div class="table-wrap"><table><thead><tr><th>模型</th><th>训练图片</th><th>精确率 P</th><th>召回率 R</th><th>mAP50</th><th>mAP50–95</th></tr></thead><tbody>${evaluated.map(m=>`<tr><td class="model-name">${esc(m.name)}<small>${m.init==='scratch'?'随机权重起步':'父模型继续训练'}</small></td><td>${m.counts.train}</td>${['precision','recall','mAP50','mAP50_95'].map(k=>`<td>${pct(m.evaluation.metrics[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('尚无测试指标','在上方启动模型评价。'))}${report?reportSections(report):panel('预标注质量与人工作时',empty('生成报告后显示','报告会对照原始预测和审核结果，并汇总已记录的人工作时。'))}`}
function reportSections(r){const rounds=r.rounds||[],counts=['unchanged','adjusted','class_changed','false_positive','missed'],labels=['几何近似','框调整','改类别','多余预测','补漏'];return `<div class="half-col">${panel('本轮预标注需要多少修正',rounds.length?`${barChart(rounds.map(x=>x.name),counts.map((c,i)=>({label:labels[i],color:COLORS[i],values:rounds.map(x=>x.counts[c])})),false)}<p class="form-help">几何近似以 IoU ≥ ${r.unchanged_iou} 判断，不等于人工未作操作。</p>`:empty('暂无已审核轮次','导入审核标注后更新报告。'))}${panel('人工作时对比',rounds.length?`${barChart(rounds.map(x=>x.name),[{label:'纯人工基线 / 分钟',color:COLORS[1],values:rounds.map(x=>x.human_time.manual.complete?x.human_time.manual.seconds/60:null)},{label:'审核修正 / 分钟',color:COLORS[0],values:rounds.map(x=>x.human_time.review.complete?x.human_time.review.seconds/60:null)}],false)}<div class="table-wrap"><table><thead><tr><th>轮次</th><th>人工基线</th><th>审核修正</th><th>工时减少</th></tr></thead><tbody>${rounds.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.human_time.manual.complete?minutes(x.human_time.manual.seconds)+' 分钟':'未完整记录'}</td><td>${x.human_time.review.complete?minutes(x.human_time.review.seconds)+' 分钟':'未完整记录'}</td><td>${pct(x.human_time.reported_time_reduction)}</td></tr>`).join('')}</tbody></table></div>`:empty('实测后比较工时','在审核页面填写纯人工与审核修正工时。'))}</div>${panel('逐轮标注质量',rounds.length?`<div class="table-wrap"><table><thead><tr><th>轮次</th><th>图片</th>${labels.map(l=>`<th>${l}</th>`).join('')}<th>P</th><th>R</th></tr></thead><tbody>${rounds.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.frames}</td>${counts.map(c=>`<td>${x.counts[c]}</td>`).join('')}<td>${pct(x.precision_at_match_iou)}</td><td>${pct(x.recall_at_match_iou)}</td></tr>`).join('')}</tbody></table></div>`:empty('暂无审核统计'))}${panel('报告与解释',`<div class="buttons"><a class="btn" href="${fileUrl('reports/report.md')}" download="report.md">下载文字报告</a><a class="btn" href="${fileUrl('reports/per_image.csv')}" download="per_image.csv">下载逐图 CSV</a><a class="btn" href="${fileUrl('reports/report.json')}" download="report.json">下载完整结果</a>${btn('打开报告目录','data-folder="reports"')}</div><p class="form-help">报告更新于 ${new Date(r.created_at).toLocaleString('zh-CN')}；新操作完成后点击上方“更新实验报告”。</p><ul class="note-list">${r.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`)}`}

function galleryFrames(roles=null,round=null){let frames=S.details.manifest.frames;if(round)frames=frames.filter(f=>round.frame_ids.includes(f.id));else if(roles)frames=frames.filter(f=>roles.includes(f.role));if(!round&&S.role!=='all')frames=frames.filter(f=>f.role===S.role);return frames}
function galleryHtml(roles=null,round=null){const allowed=roles||['unassigned','seed','pool','val','test','gap'];if(!allowed.includes(S.role))S.role='all';const frames=galleryFrames(roles,round),per=24,pages=Math.max(1,Math.ceil(frames.length/per));S.galleryPage=Math.min(S.galleryPage,pages-1);const slice=frames.slice(S.galleryPage*per,(S.galleryPage+1)*per);return `<div class="gallery-toolbar">${round?`<span class="badge">原始预测 / 审核结果</span>`:`<div class="tabs"><button data-role="all" class="${S.role==='all'?'active':''}">全部</button>${allowed.map(r=>`<button data-role="${r}" class="${S.role===r?'active':''}">${ROLE[r]}</button>`).join('')}</div>`}<span class="form-help">${frames.length} 张</span></div>${slice.length?`<div class="gallery">${slice.map(f=>`<button class="thumb" data-frame="${f.id}" ${round?`data-view-round="${esc(round.name)}"`:''}><img loading="lazy" src="${fileUrl('frames/'+f.file)}" alt="${esc(ROLE[f.role])} ${esc(frameCaption(f))}"><div class="thumb-caption"><span>${ROLE[f.role]}</span><span>${esc(frameCaption(f))}</span></div></button>`).join('')}</div><div class="buttons" style="justify-content:flex-end;margin-top:15px">${btn('← 上一页','data-gallery-page="-1" '+(!S.galleryPage?'disabled':''))}<span class="form-help">${S.galleryPage+1} / ${pages}</span>${btn('下一页 →','data-gallery-page="1" '+(S.galleryPage>=pages-1?'disabled':''))}</div>`:empty('此分组暂无图片','完成抽帧或切换图片分组。')}`}
function chartLine(rows,key,color,x,y){const segments=[];let segment=[];rows.forEach((row,index)=>{if(row[key]==null){if(segment.length)segments.push(segment);segment=[]}else segment.push([x(index),y(row[key])])});if(segment.length)segments.push(segment);return segments.map(points=>points.length===1?`<circle cx="${points[0][0]}" cy="${points[0][1]}" r="3" fill="${color}"/>`:`<polyline stroke="${color}" points="${points.map(p=>p.join(',')).join(' ')}"/>`).join('')}
function lineChart(rows,series){if(!rows?.length)return empty('等待训练记录','每完成一个 epoch，曲线会自动更新。');const valid=series.filter(([k])=>rows.some(r=>r[k]!=null));if(!valid.length)return empty('暂无此项曲线','请查看模型训练日志。');const W=650,H=215,L=43,R=16,T=17,B=30,max=Math.max(...rows.flatMap(r=>valid.map(([k])=>r[k]||0)))*1.12||1;const x=i=>L+(W-L-R)*(rows.length===1?.5:i/(rows.length-1)),y=v=>H-B-v/max*(H-T-B);return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="训练损失曲线">${[0,.25,.5,.75,1].map(t=>`<line class="grid" x1="${L}" y1="${y(max*t)}" x2="${W-R}" y2="${y(max*t)}"/><text x="${L-7}" y="${y(max*t)+3}" text-anchor="end">${(max*t).toFixed(2)}</text>`).join('')}${valid.map(([k,l,c])=>chartLine(rows,k,c,x,y)).join('')}<text x="${L}" y="${H-7}">Epoch ${rows[0].epoch}</text><text x="${W-R}" y="${H-7}" text-anchor="end">${rows.at(-1).epoch}</text></svg><div class="chart-labels">${valid.map(([k,l,c])=>`<span><i style="--legend-color:${c}"></i>${l}</span>`).join('')}</div>`}
function barChart(labels,series,percent=true){if(!labels.length)return empty('暂无数据');const W=650,H=215,L=42,R=16,T=21,B=31,n=labels.length,k=series.length,plot=W-L-R,group=plot/n,bar=Math.min(30,(group-16)/k),values=series.flatMap(s=>s.values.filter(v=>v!=null)),max=percent?1:Math.max(...values,1)*1.12,y=v=>H-B-v/max*(H-T-B);return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="结果对比柱状图">${[0,.25,.5,.75,1].map(t=>`<line class="grid" x1="${L}" y1="${y(max*t)}" x2="${W-R}" y2="${y(max*t)}"/><text x="${L-7}" y="${y(max*t)+3}" text-anchor="end">${percent?Math.round(t*100)+'%':(max*t).toFixed(max<10?1:0)}</text>`).join('')}${labels.map((l,i)=>`${series.map((s,j)=>s.values[i]==null?'':`<rect rx="3" x="${L+group*(i+.5)+(j-k/2)*bar}" y="${y(s.values[i])}" width="${Math.max(2,bar-5)}" height="${Math.max(0,H-B-y(s.values[i]))}" fill="${s.color}"><title>${esc(l)} ${esc(s.label)}: ${percent?pct(s.values[i]):s.values[i].toFixed(2)}</title></rect>`).join('')}<text x="${L+group*(i+.5)}" y="${H-7}" text-anchor="middle">${esc(l)}</text>`).join('')}</svg><div class="chart-labels">${series.map(s=>`<span><i style="--legend-color:${s.color}"></i>${esc(s.label)}</span>`).join('')}</div>${values.length?'':'<p class="form-help">未记录工时；不会以零分钟代替缺失值。</p>'}`}

function timeForm(stage,round=''){return `<form id="time-form"><div class="field-row">${select('stage','记录阶段',stage==='seed'?[['seed','种子标注']]:[['review','审核修正'],['manual','纯人工基线']],stage)}${field('seconds','实测秒数','','number','min="1" required')}</div><div class="field"><label for="f-note">备注（可选）</label><input id="f-note" name="note" placeholder="例如：第1次完整审核 / 标注人A"></div><input name="round" type="hidden" value="${esc(round)}"><div class="buttons">${btn('开始计时','type="button" id="timer-start"')}${btn('暂停并填入','type="button" id="timer-pause"')}${btn('保存工时','type="submit" '+(activeJobs().length?'disabled':''),true)}</div><div id="time-display" class="time-display">00:00:00</div><p class="form-help">计时可跨页面继续；暂停后确认秒数再保存。一次整批记录表示这一时段属于全批图片，重复记录会累加。</p></form>`}
function timeDraftKey(id=S.id,round=$('#time-form')?.elements.round.value||''){return id+'|'+round}
function timeSavePending(){return !!timeDrafts.get(timeDraftKey())?.pending}
function restoreTimeDraft(){const form=$('#time-form');if(!form)return;const draft=timeDrafts.get(timeDraftKey());if(draft){for(const [name,value] of Object.entries(draft.payload))if(form.elements.namedItem(name))form.elements.namedItem(name).value=value;form.dataset.dirty='true'}for(const input of [form.elements.stage,form.elements.seconds,form.elements.note])input.disabled=!!draft?.pending;for(const id of ['timer-start','timer-pause'])$('#'+id,form).disabled=!!draft?.pending;form.querySelector('[type="submit"]').disabled=!!draft?.pending||activeJobs().length>0}
function reconcileTimeSaves(){for(const [key,draft] of timeDrafts){if(!draft.pending||!draft.jobId)continue;const job=S.overview.jobs.find(j=>j.id===draft.jobId);if(!job||['queued','running','cancelling','recovering'].includes(job.status))continue;draft.pending=false;if(job.status==='completed'){timeDrafts.delete(key);if(draft.timer&&timerState===draft.timer)timerState=null;const form=$('#time-form');if(form&&key===timeDraftKey()){delete form.dataset.dirty;form.elements.seconds.value='';form.elements.note.value='';$('#time-display').textContent='00:00:00'}toast('工时已保存')}else{toast('工时保存失败，秒数和计时结果已保留，可查看日志后重试。',true)}}restoreTimeDraft()}
function updateCoverage(){if(S.page!=='label'||!S.details)return;for(const role of ['seed','val','test']){const coverage=S.details.coverage[role],count=$(`[data-coverage-count="${role}"]`),bar=$(`[data-coverage-bar="${role}"]`);if(count)count.innerHTML=`${coverage.saved}<small>/ ${coverage.total} 张已保存</small>`;if(bar){bar.children[0].style.setProperty('--portion',coverage.total?coverage.saved/coverage.total:0);bar.children[1].style.setProperty('--portion',coverage.total?1-coverage.saved/coverage.total:1)}}}
function timerMatches(form){return timerState&&timerState.id===S.id&&timerState.stage===form.elements.stage.value&&timerState.round===form.elements.round.value}
function updateTimer(){const el=$('#time-display'),form=$('#time-form');if(!el||!timerState)return;if(!timerMatches(form)){el.textContent=timerState.running?'其他实验或阶段正在计时':'00:00:00';return}const seconds=Math.floor((timerState.elapsed+(timerState.running?Date.now()-timerState.started:0))/1000);el.textContent=[Math.floor(seconds/3600),Math.floor(seconds/60)%60,seconds%60].map(v=>String(v).padStart(2,'0')).join(':')}

async function start(action,payload){requireProject();const job=await api('/api/job',{project_id:S.id,action,payload});if(action==='train'&&!payload.dry_run)S.trainingModel=payload.name;const formId={extract:'extract-form',split:'split-form',train:'train-form',autolabel:'auto-form',time:'time-form',evaluate:'evaluate-form','import-labels':'review-import-form'}[action];const form=document.getElementById(formId);if(form&&action!=='time')delete form.dataset.dirty;toast(`${ACTIONS[action]}已启动`);await refresh(false);updateDock();return job}
function updateDock(){const job=activeJobs()[0],dock=$('#job-dock');if(!job){dock.hidden=true;return}dock.hidden=false;dock.className='job-dock';dock.innerHTML=`<div><span class="spinner"></span>${ACTIONS[job.action]} · ${esc(job.payload.name||job.payload.round||selected()?.title||'')}<small>${job.status==='cancelling'?'已请求停止，正在等待当前步骤安全结束。':'后台执行中，你可以继续查看图片和已有结果。'}</small></div><div class="buttons">${btn('查看日志',`data-log="${job.id}"`)}${['train','extract','autolabel','evaluate'].includes(job.action)?btn('停止',`data-cancel="${job.id}" ${job.status==='cancelling'?'disabled':''}`):''}</div>`;bindCommon(dock)}
function bindCommon(root=document){
 $$('[data-go]',root).forEach(b=>b.onclick=()=>navigate(b.dataset.go));
 $$('[data-yolo]',root).forEach(b=>b.onclick=yoloDialog);$$('[data-new]',root).forEach(b=>b.onclick=createDialog);
 $$('[data-import]',root).forEach(b=>b.onclick=importDialog);
 $$('[data-folder]',root).forEach(b=>b.onclick=()=>safeAsync(async()=>{const r=await api('/api/open-folder',{project_id:S.id,location:b.dataset.folder,round:b.dataset.round||S.round,launch_app:b.hasAttribute('data-launch')});toast(b.hasAttribute('data-launch')?'标注工具和目录已打开，请在 X-AnyLabeling 中打开此目录。':'已打开：'+r.path)}));
 $$('[data-log]',root).forEach(b=>b.onclick=()=>logDialog(b.dataset.log));
 $$('[data-cancel]',root).forEach(b=>b.onclick=()=>safeAsync(async()=>{await api('/api/cancel',{id:b.dataset.cancel});toast('已请求停止任务');await refresh(false)}));
}
function bindPage(){
 bindCommon($('#content'));
 $$('#content form').forEach(form=>{form.addEventListener('input',()=>form.dataset.dirty='true');form.addEventListener('change',()=>form.dataset.dirty='true')});
 $$('[data-role]').forEach(b=>b.onclick=()=>{S.role=b.dataset.role;S.galleryPage=0;renderPage()});
 $$('[data-gallery-page]').forEach(b=>b.onclick=()=>{S.galleryPage+=Number(b.dataset.galleryPage);renderPage()});
 $$('[data-frame]').forEach(b=>b.onclick=()=>viewer(b.dataset.frame,b.dataset.viewRound));
 $$('[data-import-label]').forEach(b=>b.onclick=()=>safeAsync(()=>start('import-labels',{subset:b.dataset.importLabel})));
 const extract=$('#extract-form');if(extract)extract.onsubmit=e=>{e.preventDefault();safeAsync(async()=>{const p=formsPayload(extract);if(p.timestamps){delete p.every;p.timestamps=p.timestamps.replace(/，/g,',')}else delete p.timestamps;if(!p.end)delete p.end;S.video={path:p.video};await start('extract',p)})};
 const split=$('#split-form');if(split)split.onsubmit=e=>{e.preventDefault();safeAsync(async()=>{const p=formsPayload(split);p.val_fraction=Number(p.val_percent)/100;p.test_fraction=Number(p.test_percent)/100;delete p.val_percent;delete p.test_percent;await start('split',p)})};
 const pick=$('#pick-video');if(pick)pick.onclick=()=>safeAsync(async()=>{const r=await api('/api/pick',{kind:'video'});if(r.path){$('#video-path').value=r.path;S.video={path:r.path};await previewVideo()}});
 ['#preview-video','#seek-preview'].forEach(s=>{if($(s))$(s).onclick=()=>safeAsync(previewVideo)});
 const train=$('#train-form');if(train){const init=$('#f-init'),parent=$('#parent-field');init.onchange=()=>{parent.hidden=init.value!=='continue';$('#init-hint').textContent=init.value==='continue'?'保留父模型权重，建立新的训练周期；新增数据与额外训练会共同影响结果。':'使用实验中的结构 YAML 从零训练；不加载已有模型权重。'};$('#f-from_model').onchange=()=>{const m=completedModels().find(x=>x.name===$('#f-from_model').value);if(m)$$('input[name="rounds"]',train).forEach(i=>{if(m.rounds.includes(i.value))i.checked=true})};const submit=dry=>safeAsync(async()=>{if(!train.reportValidity())return;const p=formsPayload(train);p.rounds=$$('input[name="rounds"]:checked',train).map(i=>i.value);p.dry_run=dry;if(p.init==='scratch')delete p.from_model;else if(!p.from_model)throw new Error('请选择父模型。');await start('train',p)});train.onsubmit=e=>{e.preventDefault();submit(false)};$('#check-train').onclick=()=>submit(true)}
 if($('#f-curve-model'))$('#f-curve-model').onchange=e=>{S.trainingModel=e.target.value;renderPage(true)};
 const auto=$('#auto-form');if(auto)auto.onsubmit=e=>{e.preventDefault();safeAsync(()=>start('autolabel',formsPayload(auto)))};
 if($('#f-review-round'))$('#f-review-round').onchange=e=>{S.round=e.target.value;S.galleryPage=0;renderPage()};
 const review=$('#review-import-form');if(review)review.onsubmit=e=>{e.preventDefault();safeAsync(()=>start('import-labels',{round:S.round,reviewed:$('#review-confirm').checked}))};
 const evaluate=$('#evaluate-form');if(evaluate)evaluate.onsubmit=e=>{e.preventDefault();safeAsync(()=>{const models=$$('input[name="models"]:checked',evaluate).map(i=>i.value);if(!models.length)throw new Error('请选择尚未评价的模型。');return start('evaluate',{models,device:$('#f-device',evaluate).value})})};
 if($('#generate-report'))$('#generate-report').onclick=()=>safeAsync(()=>start('report',{}));
 const tf=$('#time-form');if(tf){tf.addEventListener('input',()=>{const draft=timeDrafts.get(timeDraftKey());if(draft&&!draft.pending)draft.payload=formsPayload(tf)});tf.addEventListener('change',()=>{const draft=timeDrafts.get(timeDraftKey());if(draft&&!draft.pending)draft.payload=formsPayload(tf)});$('#f-stage',tf).onchange=updateTimer;$('#timer-start').onclick=()=>{if(timeSavePending())return;const context={id:S.id,stage:$('#f-stage',tf).value,round:tf.elements.round.value};if(timerState&&timerState.running&&!timerMatches(tf)){toast('另一个阶段正在计时，请先回到该阶段暂停。',true);return}if(!timerMatches(tf))timerState={...context,elapsed:0,running:false};if(!timerState.running){timerState.running=true;timerState.started=Date.now()}updateTimer()};$('#timer-pause').onclick=()=>{if(!timerState)return;if(!timerMatches(tf)){toast('请回到正在计时的实验、轮次和阶段暂停，避免混入其他工时。',true);return}if(timerState.running){timerState.elapsed+=Date.now()-timerState.started;timerState.running=false}$('#f-seconds',tf).value=Math.max(1,Math.round(timerState.elapsed/1000));tf.dataset.dirty='true';const draft=timeDrafts.get(timeDraftKey());if(draft&&!draft.pending)draft.payload=formsPayload(tf);updateTimer()};tf.onsubmit=e=>{e.preventDefault();safeAsync(async()=>{const matches=timerMatches(tf);if(timeSavePending())throw new Error('工时正在保存，请等待结果。');if(matches&&timerState.running)throw new Error('请先暂停计时，再确认秒数并保存。');const p=formsPayload(tf);const key=timeDraftKey();const draft={projectId:S.id,payload:p,timer:matches?timerState:null,jobId:null,pending:true};timeDrafts.set(key,draft);tf.dataset.dirty='true';restoreTimeDraft();try{const job=await start('time',{...p,round:p.round||undefined});draft.jobId=job.id;reconcileTimeSaves();}catch(error){draft.pending=false;restoreTimeDraft();throw error;}})}}
}
async function safeAsync(fn){try{await fn()}catch(e){toast(e.message,true)}}
async function previewVideo(){const path=$('#video-path')?.value||S.video?.path;if(!path)throw new Error('请先选择视频文件。');const second=$('#f-preview-second')?.value||0;const r=await api('/api/preview-video',{path,second});S.video={path};S.preview=r;showPreview(r)}
function showPreview(r){const node=$('#video-preview');if(!node)return;node.innerHTML=`<img src="${r.image}" alt="视频预览帧">`;$('#preview-caption').textContent=`${r.width} × ${r.height} · ${r.fps.toFixed(2)} FPS · 总时长 ${r.duration.toFixed(1)} 秒`}
function openDialog(content,wide=false){dialogGeneration++;const d=$('#dialog');d.classList.toggle('wide',wide);$('#dialog-content').innerHTML=content;if(!d.open)d.showModal();bindCommon($('#dialog-content'))}
function createDialog(){openDialog(`<div class="eyebrow">NEW EXPERIMENT</div><h2>新建实验</h2><p>创建独立数据目录，保留每一轮的标注、模型和结果。</p><form id="create-form">${field('title','实验显示名称','','text','placeholder="例如：工序动作自动标注试验" required')}${field('name','目录标识','','text','placeholder="例如：workflow_test_01" pattern="[A-Za-z0-9][A-Za-z0-9_-]{0,63}" required')}<div class="field"><label for="classes">目标类别</label><textarea id="classes" name="classes" rows="3" placeholder="用逗号分隔，或每行一个类别" required></textarea><p class="form-help">名称需要与 X-AnyLabeling 标注完全一致，创建后固定。</p></div><div class="field-row">${field('seed','随机种子',42,'number','min="0" max="4294967295" required')}<div class="field"><label>模型结构</label><input value="YOLO26s-OBB" disabled></div></div>${btn('创建并准备视频','type="submit"',true)}</form>`);$('#create-form').onsubmit=e=>{e.preventDefault();safeAsync(async()=>{const p=formsPayload(e.target);p.classes=p.classes.split(/[,，\n]/).map(x=>x.trim()).filter(Boolean);const r=await api('/api/create',p);S.id=r.id;$('#dialog').close();await refresh(false);navigate('data');toast('实验已创建')})}}
function importDialog(){openDialog(`<div class="eyebrow">OPEN EXISTING EXPERIMENT</div><h2>导入已有实验</h2><p>选择包含 project.json 的实验目录。原来的模型和标注会直接显示。</p><form id="register-form"><div class="field"><label for="existing-path">实验目录</label><div class="input-action"><input id="existing-path" name="path" required placeholder="D:\\Develop\\Test\\experiments\\demo">${btn('选择目录','type="button" id="pick-existing"')}</div></div>${btn('打开实验','type="submit"',true)}</form>`);$('#pick-existing').onclick=()=>safeAsync(async()=>{const r=await api('/api/pick',{kind:'directory'});if(r.path)$('#existing-path').value=r.path});$('#register-form').onsubmit=e=>{e.preventDefault();safeAsync(async()=>{const r=await api('/api/register',formsPayload(e.target));S.id=r.id;$('#dialog').close();await refresh();toast('实验已打开')})}}
function settingsDialog(){openDialog(`<div class="eyebrow">ANNOTATION TOOL</div><h2>连接 X-AnyLabeling</h2><p>保存本机程序路径。网页会打开标注目录，并启动该程序；在程序中选择对应图片目录。</p><form id="settings-form"><div class="field"><label for="app-path">X-AnyLabeling 程序</label><div class="input-action"><input id="app-path" name="xanylabeling" value="${esc(S.overview.xanylabeling)}" placeholder="选择 X-AnyLabeling.exe" required>${btn('选择程序','type="button" id="pick-app"')}</div></div>${btn('保存设置','type="submit"',true)}</form>`);$('#pick-app').onclick=()=>safeAsync(async()=>{const r=await api('/api/pick',{kind:'app'});if(r.path)$('#app-path').value=r.path});$('#settings-form').onsubmit=e=>{e.preventDefault();safeAsync(async()=>{await api('/api/settings',formsPayload(e.target));await refresh(false);$('#dialog').close();toast('标注工具设置已保存')})}}
async function logDialog(id){openDialog(`<div class="eyebrow">TASK LOG</div><h2>${ACTIONS[S.overview.jobs.find(j=>j.id===id)?.action]||'任务日志'}</h2><p>任务进度与错误信息原样保留。</p><pre id="dialog-log" class="log" data-id="${id}">正在读取日志…</pre>`);await safeAsync(async()=>{$('#dialog-log').textContent=(await api('/api/log?id='+id)).text||'任务准备中…'})}
async function optionalDocument(path){try{const response=await fetch(fileUrl(path));if(!response.ok)return null;return await response.json()}catch{return null}}
async function viewer(frameId,roundName){
 const frames=roundName?S.details.manifest.frames.filter(f=>S.details.rounds.find(r=>r.name===roundName)?.frame_ids.includes(f.id)):galleryFrames(S.page==='label'?['seed','val','test']:null);const index=frames.findIndex(f=>f.id===frameId),frame=frames[index];if(!frame)return;
 const pair=!!roundName;openDialog(`<div class="eyebrow">FRAME INSPECTION</div><h2>${ROLE[frame.role]} · ${esc(frameCaption(frame))}</h2><p>${esc(frame.source_name||frame.file)} · ${frame.width} × ${frame.height}</p><div class="${pair?'viewer-pair':'viewer-panel'}">${pair?'<div class="viewer-panel"><h3>原始预测 · 保留不修改</h3><canvas id="view-raw"></canvas><p id="raw-info"></p></div><div class="viewer-panel"><h3>审核结果 · 当前编辑 / 已归档</h3><canvas id="view-reviewed"></canvas><p id="review-info"></p></div>':'<canvas id="view-single"></canvas><p id="single-info"></p>'}</div><div class="viewer-nav">${btn('← 上一张','id="view-prev" '+(!index?'disabled':''))}<span>${index+1} / ${frames.length}</span>${btn('下一张 →','id="view-next" '+(index===frames.length-1?'disabled':''))}</div>`,true);
 $('#view-prev').onclick=()=>viewer(frames[index-1].id,roundName);$('#view-next').onclick=()=>viewer(frames[index+1].id,roundName);
 const generation=dialogGeneration,projectId=S.id,current=()=>generation===dialogGeneration&&projectId===S.id&&$('#dialog').open;const image=new Image();image.src=fileUrl('frames/'+frame.file);await image.decode();if(!current())return;
 if(pair){const round=S.details.rounds.find(r=>r.name===roundName);const docs=await Promise.all([optionalDocument(`rounds/${roundName}/raw/${frame.id}.json`),optionalDocument(round.status==='reviewed'?`annotations/${round.annotation_key}/${frame.id}.json`:`rounds/${roundName}/editable/${frame.id}.json`)]);if(!current())return;drawBoxes($('#view-raw'),image,docs[0]);drawBoxes($('#view-reviewed'),image,docs[1]);if($('#raw-info'))$('#raw-info').textContent=docs[0]?`${docs[0].shapes.length} 个预测框，显示类别与置信度。`:'原始预测不存在。';if($('#review-info'))$('#review-info').textContent=docs[1]?`${docs[1].shapes.length} 个框 · ${round.status==='reviewed'?'已人工确认并归档':'尚未归档，编辑目录可能仍是原始预测。'}`:'尚无审核标注。'}else{const key=frame.role,doc=await optionalDocument(`${S.details.annotations[key]?`annotations/${key}`:`workspaces/${key}`}/${frame.id}.json`);if(!current())return;drawBoxes($('#view-single'),image,doc);if($('#single-info'))$('#single-info').textContent=doc?`${doc.shapes.length} 个框 · ${S.details.annotations[key]?'已归档人工标注':'当前标注文件，尚未归档'}`:'未保存标注；不是已确认的负样本。'}
}
function drawBoxes(canvas,image,doc){if(!canvas)return;canvas.width=image.naturalWidth;canvas.height=image.naturalHeight;const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0);const scale=Math.max(1,image.naturalWidth/700);ctx.lineWidth=2.4*scale;ctx.font=`${12*scale}px Segoe UI,Microsoft YaHei`;for(const shape of doc?.shapes||[]){let pts=shape.points;if(pts.length===2&&shape.shape_type==='rectangle'){const[a,b]=pts;pts=[a,[b[0],a[1]],b,[a[0],b[1]]]}if(!pts.length)continue;const color=COLORS[Math.max(0,S.details.config.classes.indexOf(shape.label))%COLORS.length];ctx.beginPath();pts.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.strokeStyle=color;ctx.stroke();const label=shape.label+(shape.score!=null?' '+Number(shape.score).toFixed(2):'');const tx=Math.max(0,Math.min(pts[0][0],canvas.width-ctx.measureText(label).width-8)),ty=Math.max(16*scale,pts[0][1]);ctx.fillStyle=color;ctx.fillRect(tx,ty-17*scale,ctx.measureText(label).width+8*scale,19*scale);ctx.fillStyle='white';ctx.fillText(label,tx+4*scale,ty-3*scale)}}

