async function poll(){if(pollBusy)return;pollBusy=true;try{const old=activeJobs().map(j=>j.id).join(','),had=activeJobs().length;if(!await refresh(false))return;updateCoverage();const changed=old!==activeJobs().map(j=>j.id).join(',');if(changed&&had){renderPage(true);toast('任务已结束，结果已刷新。')}else if(activeJobs().length&&['overview','train'].includes(S.page)&&!$('#content').contains(document.activeElement)&&!$('#dialog').open)renderPage(true);const log=$('#dialog-log');if(log&&$('#dialog').open)log.textContent=(await api('/api/log?id='+log.dataset.id)).text||'任务准备中…'}catch(e){console.warn(e)}finally{pollBusy=false}}
(async()=>{try{const boot=await api('/api/bootstrap');S.token=boot.token;S.overview=boot;await refresh();setInterval(poll,2500);setInterval(updateTimer,500)}catch(e){$('#content').innerHTML=`<div class="error-box">无法连接工作台：${esc(e.message)}。请刷新页面或重新启动服务。</div>`}})();
